"""Round-robin budget: updates_per_second is a legacy-named structures/tick cap.
Every loaded root is selected once per round; native selectors implement the queue.
"""
DIMS=['overworld','the_nether','the_end']
fn('config/defaults',[f'execute unless score #{k} vr.cfg matches {lo}..{hi} run scoreboard players set #{k} vr.cfg {default}' for k,lo,hi,default in [('ups',1,256,20),('substeps',1,8,2),('solver',1,16,4),('step_ticks',1,20,1),('enabled',0,1,1)]])
fn('api/configure',*[f'$scoreboard players set #new_{name} vr.cfg $({arg})' for name,arg in [('ups','updates_per_second'),('substeps','substeps'),('solver','solver_iterations'),('step_ticks','step_ticks')]],*[f'execute unless score #new_{name} vr.cfg matches {lo}..{hi} run return 0' for name,lo,hi in [('ups',1,256),('substeps',1,8),('solver',1,16),('step_ticks',1,20)]],*[f'scoreboard players operation #{name} vr.cfg = #new_{name} vr.cfg' for name in ['ups','substeps','solver','step_ticks']],'return 1')
fn('api/set_budget','$scoreboard players set #new_budget vr.cfg $(structures_per_tick)','execute unless score #new_budget vr.cfg matches 1..256 run return 0','scoreboard players operation #ups vr.cfg = #new_budget vr.cfg','return 1')
fn('api/config_status','tellraw @s [{text:"VR structures/tick="},{score:{name:"#ups",objective:"vr.cfg"}},{text:" substeps="},{score:{name:"#substeps",objective:"vr.cfg"}},{text:" solver iterations="},{score:{name:"#solver",objective:"vr.cfg"}},{text:" simulated ticks/activation="},{score:{name:"#step_ticks",objective:"vr.cfg"}}]')
fn('tick','execute unless score #enabled vr.cfg matches 1 run return 0','execute unless score #ups vr.cfg matches 1..256 run return 0',[f'scoreboard players set #{x} vr.stat 0' for x in ['sat','bvh','linear','world','contacts','overflow','pairs','processed']], 'scoreboard players set #loaded vr.stat 0','scoreboard players set #pending vr.tmp 0',*[f'execute in minecraft:{d} run function vr:scheduler/count' for d in DIMS],'execute if score #loaded vr.stat matches 0 run return 0','execute if score #pending vr.tmp matches 0 run function vr:scheduler/new_round','scoreboard players operation #budget_left vr.tmp = #ups vr.cfg',*[f'execute in minecraft:{d} run function vr:scheduler/dimension' for d in DIMS])
fn('scheduler/count','execute store result score #local_count vr.tmp run execute if entity @e[type=minecraft:marker,tag=vr.root]','scoreboard players operation #loaded vr.stat += #local_count vr.tmp','execute store result score #local_pending vr.tmp run execute if entity @e[type=minecraft:marker,tag=vr.root,tag=!vr.round_done]','scoreboard players operation #pending vr.tmp += #local_pending vr.tmp')
fn('scheduler/new_round',*[f'execute in minecraft:{d} run tag @e[type=minecraft:marker,tag=vr.root] remove vr.round_done' for d in DIMS],'scoreboard players add #round vr.cfg 1')
fn('scheduler/dimension','execute if score #budget_left vr.tmp matches ..0 run return 0','execute unless entity @e[type=minecraft:marker,tag=vr.root,tag=!vr.round_done] run return 0','tag @e[type=minecraft:marker,tag=vr.root] remove vr.selected','tag @e[type=minecraft:marker,tag=vr.root] remove vr.a','execute store result storage vr:work scheduling.budget int 1 run scoreboard players get #budget_left vr.tmp','function vr:scheduler/pick with storage vr:work scheduling','function vr:config/prepare','scoreboard players operation #subleft vr.tmp = #substeps vr.cfg','function vr:scheduler/substeps','execute as @e[type=minecraft:marker,tag=vr.root,tag=vr.selected] at @s run function vr:render/body','execute as @e[type=minecraft:marker,tag=vr.root,tag=vr.render_dirty,tag=!vr.selected] at @s run function vr:render/body','tag @e[type=minecraft:marker,tag=vr.root] remove vr.render_dirty','tag @e[type=minecraft:marker,tag=vr.root] remove vr.selected')
fn('scheduler/pick','$execute as @e[type=minecraft:marker,tag=vr.root,tag=!vr.round_done,limit=$(budget)] run function vr:scheduler/mark')
fn('scheduler/mark','tag @s add vr.selected','tag @s add vr.round_done','scoreboard players remove #budget_left vr.tmp 1','scoreboard players add #processed vr.stat 1','scoreboard players add @s vr.updates 1')
fn('scheduler/substeps','execute if score #subleft vr.tmp matches ..0 run return 0','execute as @e[type=minecraft:marker,tag=vr.root,tag=vr.selected] at @s run function vr:body/integrate','execute as @e[type=minecraft:marker,tag=vr.root,tag=vr.selected,tag=!vr.frozen] at @s run function vr:body/world','execute as @e[type=minecraft:marker,tag=vr.root,tag=vr.selected,tag=!vr.frozen] at @s run function vr:scheduler/pair_outer','scoreboard players remove #subleft vr.tmp 1','return run function vr:scheduler/substeps')
# Selected A must also collide with an unselected lower-ID neighbor. For two
# selected roots preserve the existing once-per-unordered-pair ID ordering.
fn('scheduler/pair_outer','tag @s add vr.a','scoreboard players operation #aid vr.tmp = @s vr.id','execute as @e[type=minecraft:marker,tag=vr.root,tag=!vr.a,tag=!vr.frozen,distance=..17] unless entity @s[tag=vr.selected] run function vr:pair/body','execute as @e[type=minecraft:marker,tag=vr.root,tag=!vr.a,tag=!vr.frozen,distance=..17] if entity @s[tag=vr.selected] if score @s vr.id > #aid vr.tmp run function vr:pair/body','tag @s remove vr.a')
# Passive collision partners need immediate visual synchronization too.
p=F/'pair/body.mcfunction';s=p.read_text();s=s.replace('function vr:contact/solve_all','execute if data storage vr:work contacts[0] run tag @s add vr.render_dirty\nfunction vr:contact/solve_all');write(p,s)
# Tests of configuration validation are read-only to world state; old frequency
# tests no longer apply to the new meaning and are replaced.
ls=['scoreboard objectives add vr.test dummy','scoreboard players set #config_fail vr.test 0']
for k in ['ups','substeps','solver','step_ticks']:
 ls += [f'scoreboard players operation #save_{k} vr.cfg = #{k} vr.cfg']
ls += ['execute store result score #valid vr.test run function vr:api/configure {updates_per_second:32,substeps:2,solver_iterations:4,step_ticks:1}','execute unless score #valid vr.test matches 1 run scoreboard players add #config_fail vr.test 1','execute unless score #ups vr.cfg matches 32 run scoreboard players add #config_fail vr.test 1','execute store result score #invalid vr.test run function vr:api/set_budget {structures_per_tick:0}','execute unless score #invalid vr.test matches 0 run scoreboard players add #config_fail vr.test 1','execute unless score #ups vr.cfg matches 32 run scoreboard players add #config_fail vr.test 1']
for k in ['ups','substeps','solver','step_ticks']:
 ls += [f'scoreboard players operation #{k} vr.cfg = #save_{k} vr.cfg']
ls += ['return run scoreboard players get #config_fail vr.test']
fn('test/configuration',ls)
fn('api/scheduler_stats','tellraw @s [{text:"Loaded="},{score:{name:"#loaded",objective:"vr.stat"}},{text:" actively processed this tick="},{score:{name:"#processed",objective:"vr.stat"}},{text:" round="},{score:{name:"#round",objective:"vr.cfg"}}]')
